D=/sys/kernel/debug/dispsys
rd() { echo "regr_pa:$1" > $D; cat $D | grep -o 'regr_pa.*' ; }
for base in 1401b000 1401c000; do for off in 00 04 08 0c 10 14 18 1c 20 24 28 2c 50 54 58 5c 60 64 90 100 104 108 110 114 118 11c 120 130; do rd $(printf '%x' $((0x$base + 0x$off))); done; done
for a in 10215000 10215004 10215008 1021500c 10215010 10215014 10215040 10215044 10215050 10215054 10215058 1021505c 10215060 10215064 10215068 10215070 10215080 10215084 10216050 10216058; do rd $a; done
for a in 14000008 14000040 14000048 14000050 14000084 140000a0 140000a4 140000a8 140000b0 14000100 14000110 1401a000 1401a004 1401a008 1401a050 1401a054 1401a058 14019000 14019008 1400e000 1400e010 1400e040 1400e044 14023000 14023020 14015000 14015020 14013400 14013c00 14020020 1402002c 14020030; do rd $a; done
